import {
  createForks,
  teardownForks,
  createWorkspace,
  teardownWorkspace,
  Forks,
  Workspace,
} from "@tigrisdata/agent-kit";
import {
  S3Client,
  GetObjectCommand,
  PutObjectCommand,
} from "@aws-sdk/client-s3";
import fs from "fs/promises";

const TIGRIS_ENDPOINT = "REDACTED";
const TIGRIS_REGION = "REDACTED";
const GOLD_BUCKET = "gold-eval-dataset";

const config = {
  endpoint: TIGRIS_ENDPOINT,
  accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID,
  secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY,
};

async function main() {
  let forks: Forks | undefined;
  const workspaces: Workspace[] = [];
  const forkToWorkspace = new Map<string, Workspace>();

  try {
    // 1. Fork gold-eval-dataset into exactly 3 isolated environments
    const forksResponse = await createForks(GOLD_BUCKET, 3, {
      prefix: "eval-attempt",
      credentials: { role: "ReadOnly" },
      config,
    });

    if (forksResponse.error) {
      throw forksResponse.error;
    }
    forks = forksResponse.data;

    // 2. For each fork, provision a separate write workspace and process prompts
    await Promise.all(
      forks.forks.map(async (fork, i) => {
        const workspaceResponse = await createWorkspace(`eval-writer-${i}`, {
          credentials: { role: "Editor" },
          config,
        });

        if (workspaceResponse.error) {
          throw workspaceResponse.error;
        }
        const workspace = workspaceResponse.data;
        workspaces.push(workspace);
        forkToWorkspace.set(fork.bucket, workspace);

        const forkS3 = new S3Client({
          endpoint: TIGRIS_ENDPOINT,
          region: TIGRIS_REGION,
          credentials: fork.credentials!,
        });

        const workspaceS3 = new S3Client({
          endpoint: TIGRIS_ENDPOINT,
          region: TIGRIS_REGION,
          credentials: workspace.credentials!,
        });

        const prompts = ["p1", "p2", "p3"];
        for (const p of prompts) {
          const promptKey = `prompts/${p}.json`;
          const getObj = await forkS3.send(
            new GetObjectCommand({
              Bucket: fork.bucket,
              Key: promptKey,
            })
          );
          const body = await getObj.Body?.transformToString();
          if (body === undefined) {
            throw new Error(`Empty body for ${promptKey} in fork ${fork.bucket}`);
          }

          const reversed = body.split("").reverse().join("");
          const answerKey = `answers/${p}.txt`;

          await workspaceS3.send(
            new PutObjectCommand({
              Bucket: workspace.bucket,
              Key: answerKey,
              Body: reversed,
            })
          );
        }
      })
    );

    // 3. Aggregate answers from workspaces
    const aggregated: Record<string, Record<string, string>> = {};
    for (const fork of forks.forks) {
      const workspace = forkToWorkspace.get(fork.bucket)!;
      const workspaceS3 = new S3Client({
        endpoint: TIGRIS_ENDPOINT,
        region: TIGRIS_REGION,
        credentials: workspace.credentials!,
      });

      const answers: Record<string, string> = {};
      const prompts = ["p1", "p2", "p3"];
      for (const p of prompts) {
        const answerKey = `answers/${p}.txt`;
        const getObj = await workspaceS3.send(
          new GetObjectCommand({
            Bucket: workspace.bucket,
            Key: answerKey,
          })
        );
        const content = await getObj.Body?.transformToString();
        if (content === undefined) {
          throw new Error(`Empty content for ${answerKey} in workspace ${workspace.bucket}`);
        }
        answers[p] = content;
      }
      aggregated[fork.bucket] = answers;
    }

    await fs.writeFile(
      "/home/user/orchestrator/aggregated.json",
      JSON.stringify(aggregated, null, 2)
    );
    console.log("Successfully aggregated results to aggregated.json");

  } catch (err) {
    console.error("Error during execution:", err);
    process.exit(1);
  } finally {
    // 4. Tear down every fork and writer workspace
    console.log("Cleaning up...");
    if (forks) {
      try {
        await teardownForks(forks, { config });
      } catch (e) {
        console.error("Error tearing down forks:", e);
      }
    }
    for (const workspace of workspaces) {
      try {
        await teardownWorkspace(workspace, { config });
      } catch (e) {
        console.error(`Error tearing down workspace ${workspace.bucket}:`, e);
      }
    }
  }
}

main().catch((err) => {
  console.error("Unhandled error:", err);
  process.exit(1);
});

